from pathlib import Path
import subprocess,sys
root=Path(__file__).parent.parent
out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=True)
source=(root/'windows/native-dv/src/persistent_engine.inc').read_text()
helper=source[source.index('// Separate MediaEngine'):source.index('struct PersistentEngine')]
head='#include <windows.h>\n#include <d3d11_4.h>\n#include <d3d10.h>\n#include <dxgi1_2.h>\n#include <wrl/client.h>\n#include <memory>\n#include <vector>\n#include <cassert>\n#include <iostream>\n#include <string>\nusing Microsoft::WRL::ComPtr;\nstruct Failure { HRESULT hr; const char* site; };\n#define CK(x) do {HRESULT hr_=(x);if(FAILED(hr_))throw Failure{hr_,#x};}while(0)\n'
body='int main(){try{\n ComPtr<IDXGIFactory1> factory;CK(CreateDXGIFactory1(IID_PPV_ARGS(&factory)));\n ComPtr<IDXGIAdapter1> adapter;\n for(UINT n=0;;n++){ComPtr<IDXGIAdapter1> a;if(factory->EnumAdapters1(n,&a)==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 d{};CK(a->GetDesc1(&d));if(d.VendorId==0x10de){adapter=a;break;}}\n assert(adapter);\n ComPtr<ID3D11Device>a,b;ComPtr<ID3D11DeviceContext>ac,bc;\n CK(D3D11CreateDevice(adapter.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&a,nullptr,&ac));\n CK(D3D11CreateDevice(adapter.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&b,nullptr,&bc));\n SharedGpuSurface inputs[8],outputs[8];for(auto& x:inputs)x.init(a.Get(),b.Get(),128,64,DXGI_FORMAT_R8G8B8A8_UNORM);for(auto& x:outputs)x.init(a.Get(),b.Get(),128,64,DXGI_FORMAT_R8G8B8A8_UNORM);\n assert(inputs[0].fenced&&outputs[0].fenced);\n D3D11_TEXTURE2D_DESC td{};td.Width=128;td.Height=64;td.MipLevels=1;td.ArraySize=1;td.SampleDesc.Count=1;td.Format=DXGI_FORMAT_R8G8B8A8_UNORM;td.Usage=D3D11_USAGE_DEFAULT;td.BindFlags=D3D11_BIND_SHADER_RESOURCE;\n ComPtr<ID3D11Texture2D>src,mid;CK(a->CreateTexture2D(&td,nullptr,&src));CK(b->CreateTexture2D(&td,nullptr,&mid));\n std::vector<ComPtr<ID3D11Texture2D>>dest(64);\n for(int n=0;n<64;n++){\n   auto& input=inputs[n%8];auto& output=outputs[n%8];\n   CK(a->CreateTexture2D(&td,nullptr,&dest[n]));std::vector<unsigned char> pixels(128*64*4,(unsigned char)(n+1));\n   ac->UpdateSubresource(src.Get(),0,nullptr,pixels.data(),128*4,0);\n   {SurfaceLease l(input,true,0,1);ac->CopyResource(input.caller.Get(),src.Get());l.release();}\n   {SurfaceLease l(input,false,1,0);bc->CopyResource(mid.Get(),input.renderer.Get());l.release();}\n   {SurfaceLease l(output,false,0,1);bc->CopyResource(output.renderer.Get(),mid.Get());l.release();}\n   {SurfaceLease l(output,true,1,0);ac->CopyResource(dest[n].Get(),output.caller.Get());l.release();}\n }\n // Readback only belongs to this bounded correctness fixture, never playback.\n td.Usage=D3D11_USAGE_STAGING;td.BindFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;\n ComPtr<ID3D11Texture2D>staging;CK(a->CreateTexture2D(&td,nullptr,&staging));\n for(int n=0;n<64;n++){ac->CopyResource(staging.Get(),dest[n].Get());D3D11_MAPPED_SUBRESOURCE m{};CK(ac->Map(staging.Get(),0,D3D11_MAP_READ,0,&m));\n  for(int y=0;y<64;y++)for(int x=0;x<128*4;x++)assert(((unsigned char*)m.pData)[y*m.RowPitch+x]==n+1);\n  ac->Unmap(staging.Get(),0);\n }\n for(auto& x:inputs)assert(x.sequence==16);for(auto& x:outputs)assert(x.sequence==16);\n std::cout<<"PASS: 64 queued round trips, exact pixels, ordered reuse\\n";\n return 0;\n}catch(Failure e){std::cerr<<e.site<<" HRESULT "<<std::hex<<e.hr<<"\\n";return 1;}}\n'
assert 'input_slot++%8' in source and 'output_shared[rendered%8]' in source
for name in ['fence-unorm','fence-fp16','legacy-unorm']:
    code=helper;test=body
    if name=='legacy-unorm':
        # Simulate absent Device5; exercise the real legacy branch on a new GPU.
        code=code.replace('if(SUCCEEDED(a->QueryInterface','if(false && SUCCEEDED(a->QueryInterface',1)
        test=test.replace('assert(inputs[0].fenced&&outputs[0].fenced);','assert(!inputs[0].fenced&&!outputs[0].fenced);').replace('assert(x.sequence==16)','assert(x.sequence==0)')
    if name=='fence-fp16':
        test=test.replace('DXGI_FORMAT_R8G8B8A8_UNORM','DXGI_FORMAT_R16G16B16A16_FLOAT').replace('128*64*4','128*64*8').replace('128*4','128*8')
    src=out/(name+'.cpp');exe=out/(name+'.exe');src.write_text(head+code+test)
    subprocess.run(['cl','/nologo','/std:c++17','/EHsc','/W4','/utf-8','/O2','/MT',str(src),'/Fe:'+str(exe),'/Fo:'+str(out/(name+'.obj')),'/link','d3d11.lib','dxgi.lib'],cwd=out,check=True)
    subprocess.run([str(exe)],cwd=out,check=True)
print('PASS: UNORM, FP16 and checked legacy fallback; 64 ordered round trips each')
